import { QueryClient, dehydrate, HydrationBoundary } from '@tanstack/react-query';

async function Page({ params }: { params: { id: string } }) {
  const queryClient = new QueryClient({
    defaultOptions: {
      queries: {
        staleTime: 1000 * 60 * 5
      }
    }
  });

  await queryClient.prefetchQuery({
    queryKey: ['todos', params.id],
    queryFn: () => fetchTodos(params.id)
  });

  return (
    <HydrationBoundary state={dehydrate(queryClient)}>
      <TodoDetail id={params.id} />
    </HydrationBoundary>
  );
}

async function DashboardPage() {
  const queryClient = new QueryClient();

  await Promise.all([
    queryClient.prefetchQuery({ queryKey: ['revenue'], queryFn: fetchRevenue }),
    queryClient.prefetchQuery({ queryKey: ['users'], queryFn: fetchUsers }),
    queryClient.prefetchQuery({ queryKey: ['orders'], queryFn: fetchOrders })
  ]);

  return (
    <HydrationBoundary state={dehydrate(queryClient)}>
      <DashboardClient />
    </HydrationBoundary>
  );
}

async function ProductPage({ params }: { params: { id: string } }) {
  const queryClient = new QueryClient();

  // Hydrate critical above-the-fold data
  await queryClient.prefetchQuery({
    queryKey: ['product', params.id],
    queryFn: () => fetchProduct(params.id)
  });

  // Skip hydrating reviews; fetch client-side
  // await queryClient.prefetchQuery({ queryKey: ['reviews', params.id], ... });

  return (
    <HydrationBoundary state={dehydrate(queryClient)}>
      <ProductClient id={params.id} />
    </HydrationBoundary>
  );
}
